    /// A second connection to a test store's file must present the same key,
    /// exactly like production's keyed open.
    fn keyed_observer(store: &Store) -> Connection {
        let conn = Connection::open(store.path()).unwrap();
        conn.execute_batch(&format!(
            "PRAGMA key = \"x'{}'\"",
            hex::encode(TEST_KEY_BYTES)
        ))
        .unwrap();
        conn
    }

    #[test]
    fn account_message_idempotency_and_pagination() {
        let temp = TempDir::new().unwrap();
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(temp.path(), std::fs::Permissions::from_mode(0o700)).unwrap();
        }
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let message = MessageRecord {
            author_aci: None,
            id: "m1".into(),
            account_id: account.id.clone(),
            conversation_id: conversation.id.clone(),
            direction: "outgoing",
            sender_id: "self".into(),
            sender_name: None,
            mentions_self: false,
            sent_at: 10,
            received_at: None,
            text: Some("hello".into()),
            text_bytes: Some(5),
            text_truncated: false,
            text_retrievable: true,

            status: "sent",
            client_request_id: Some("client-1".into()),
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            edited_at: None,
            rich: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        assert!(
            store
                .insert_message(&message, Some("client-1"), Some("hello"), false)
                .unwrap()
        );
        assert!(
            !store
                .insert_message(&message, Some("client-1"), Some("hello"), false)
                .unwrap()
        );
        let again = store
            .message_by_client_request(&account.id, "client-1")
            .unwrap()
            .unwrap();
        assert_eq!(again.id, "m1");
        assert_eq!(again.client_request_id.as_deref(), Some("client-1"));
        let page = store
            .list_messages(&account.id, &conversation.id, 10, None)
            .unwrap();
        assert_eq!(page.items.len(), 1);
    }

    /// Contract 1.25: a rich-body payload persists in the rich_json column,
    /// round-trips through reads, and flattens onto the wire row as top-level
    /// previews/mentions/textStyles/viewOnce; a plain row stays key-absent.
    #[test]
    fn rich_payload_round_trips_and_flattens_on_the_wire() {
        use crate::engine::{NormalizedMention, NormalizedPreview, NormalizedRich};
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let base = |id: &str| MessageRecord {
            author_aci: None,
            id: id.into(),
            account_id: account.id.clone(),
            conversation_id: conversation.id.clone(),
            direction: "incoming",
            sender_id: "peer".into(),
            sender_name: None,
            mentions_self: false,
            sent_at: 10,
            received_at: None,
            text: Some("body".into()),
            text_bytes: Some(4),
            text_truncated: false,
            text_retrievable: true,
            status: "delivered",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            edited_at: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };

        let mut rich = base("rich-1");
        rich.rich = Some(NormalizedRich {
            previews: vec![NormalizedPreview {
                url: "https://example.com/a".into(),
                title: Some("Title".into()),
                description: None,
                date: None,
                image: None,
            }],
            mentions: vec![NormalizedMention {
                author: "+15555550101".into(),
                author_aci: None,
                name: Some("Peer".into()),
                start: 0,
                length: 4,
            }],
            text_styles: vec![crate::engine::NormalizedTextStyle {
                style: "BOLD".into(),
                start: 0,
                length: 4,
            }],
            view_once: true,
            ..crate::engine::NormalizedRich::default()
        });
        assert!(
            store
                .insert_message(&rich, None, Some("body"), true)
                .unwrap()
        );
        let read = store
            .message_by_id(&account.id, &conversation.id, "rich-1")
            .unwrap();
        let read = read.unwrap();
        let stored = read.rich.as_ref().expect("rich round-trips");
        assert_eq!(stored.previews[0].url, "https://example.com/a");
        assert_eq!(stored.mentions[0].author, "+15555550101");
        assert_eq!(stored.text_styles[0].style, "BOLD");
        assert!(stored.view_once);
        let wire = serde_json::to_value(&read).unwrap();
        assert_eq!(wire["previews"][0]["url"], "https://example.com/a");
        assert_eq!(wire["mentions"][0]["author"], "+15555550101");
        assert_eq!(wire["textStyles"][0]["style"], "BOLD");
        assert_eq!(wire["viewOnce"], true);

        // Contract 1.40 (§4.40): an authorAci on the mention round-trips and
        // lands on the wire row beside the unchanged author; a mention
        // without one stays byte-identical to the pre-1.40 wire shape.
        let mut aci = base("rich-aci");
        aci.rich = Some(NormalizedRich {
            mentions: vec![NormalizedMention {
                author: "+15555550101".into(),
                author_aci: Some("0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10".into()),
                name: None,
                start: 0,
                length: 4,
            }],
            ..crate::engine::NormalizedRich::default()
        });
        assert!(
            store
                .insert_message(&aci, None, Some("body"), true)
                .unwrap()
        );
        let read = store
            .message_by_id(&account.id, &conversation.id, "rich-aci")
            .unwrap()
            .unwrap();
        let wire = serde_json::to_value(&read).unwrap();
        assert_eq!(wire["mentions"][0]["author"], "+15555550101");
        assert_eq!(
            wire["mentions"][0]["authorAci"],
            "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10"
        );
        let bare = serde_json::to_value(&read.rich.as_ref().unwrap().mentions[0]).unwrap();
        assert_eq!(bare["author"], "+15555550101");
        assert_eq!(bare["authorAci"], "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10");

        // A pre-1.40 rich_json (no authorAci key) deserializes with the field
        // absent and projects nothing — old rows need no rewrite.
        let legacy: crate::engine::NormalizedRich = serde_json::from_str(
            r#"{"mentions":[{"author":"+15555550101","start":0,"length":4}]}"#,
        )
        .unwrap();
        assert_eq!(legacy.mentions[0].author, "+15555550101");
        assert_eq!(legacy.mentions[0].author_aci, None);
        let legacy_wire = serde_json::to_value(&legacy.mentions[0]).unwrap();
        assert!(legacy_wire.get("authorAci").is_none());

        assert!(
            store
                .insert_message(&base("plain-1"), None, Some("body"), true)
                .unwrap()
        );
        let plain = store
            .message_by_id(&account.id, &conversation.id, "plain-1")
            .unwrap()
            .unwrap();
        assert!(plain.rich.is_none());
        let plain_wire = serde_json::to_value(&plain).unwrap();
        assert!(plain_wire.get("previews").is_none());
        assert!(plain_wire.get("viewOnce").is_none());
    }

    /// Contract 1.93 (§4.76): the adjacent visual-media probe walks the
    /// keyset in the probe direction, adjacency-first with the anchor itself
    /// never returned; only rows with an image/* or video/* attachment match
    /// (audio/file/unclassified honestly skip), view-once rows never join,
    /// and a media message in another conversation stays invisible.
    #[test]
    fn list_adjacent_media_walks_both_directions_with_the_strip_predicate() {
        use crate::engine::{NormalizedAttachment, NormalizedRich};
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let other = store
            .ensure_conversation(&account.id, "direct", "+15555550102", "other")
            .unwrap();
        let attachment = |id: &str, content_type: Option<&str>| NormalizedAttachment {
            id: id.into(),
            content_type: content_type.map(str::to_string),
            filename: None,
            size: Some(1024),
            width: None,
            height: None,
            is_voice_note: false,
            caption: None,
            blur_hash: None,
            incremental_mac: None,
            chunk_size: None,
            is_borderless: false,
            is_gif: false,
            locator: None,
            waveform: None,
            duration: None,
        };
        let row = |id: &str,
                   sent_at: u64,
                   attachments: Vec<NormalizedAttachment>,
                   rich: Option<NormalizedRich>|
         -> MessageRecord {
            MessageRecord {
                author_aci: None,
                id: id.into(),
                account_id: account.id.clone(),
                conversation_id: conversation.id.clone(),
                direction: "incoming",
                sender_id: "peer".into(),
                sender_name: None,
                mentions_self: false,
                sent_at,
                received_at: None,
                text: None,
                text_bytes: None,
                text_truncated: false,
                text_retrievable: false,
                status: "delivered",
                client_request_id: None,
                quote_message_id: None,
                quote_snapshot: None,
                quote: None,
                attachments,
                rich,
                edited_at: None,
                reactions: Vec::new(),
                edits: Vec::new(),
                delivered_at: None,
                read_at: None,
                viewed_at: None,
                send_outcomes: None,
                admin_deleted: false,
                sticker: None,
                expire_seconds: None,
                expire_start_at: None,
                server_guid: None,
                server_timestamp: None,
                is_story: false,
                story_message: None,
            }
        };
        let insert = |message: &MessageRecord| {
            store.insert_message(message, None, None, false).unwrap();
        };
        // Timeline (sent_at order): 10 image, 20 text-only, 30 audio,
        // 40 video, 50 anchor text, 60 pdf, 70 view-once image, 80 image.
        insert(&row(
            "m-image-10",
            10,
            vec![attachment("a10", Some("image/jpeg"))],
            None,
        ));
        insert(&row("m-text-20", 20, vec![], None));
        insert(&row(
            "m-audio-30",
            30,
            vec![attachment("a30", Some("audio/aac"))],
            None,
        ));
        insert(&row(
            "m-video-40",
            40,
            vec![attachment("a40", Some("video/mp4"))],
            None,
        ));
        insert(&row("m-anchor-50", 50, vec![], None));
        insert(&row(
            "m-pdf-60",
            60,
            vec![attachment("a60", Some("application/pdf"))],
            None,
        ));
        insert(&row(
            "m-viewonce-70",
            70,
            vec![attachment("a70", Some("image/png"))],
            Some(NormalizedRich {
                view_once: true,
                ..NormalizedRich::default()
            }),
        ));
        insert(&row(
            "m-image-80",
            80,
            vec![attachment("a80", Some("image/png"))],
            None,
        ));
        // An unclassifiable attachment (no content type) never matches.
        insert(&row(
            "m-mystery-90",
            90,
            vec![attachment("a90", None)],
            None,
        ));
        // Media in another conversation is invisible to the probe.
        let mut cross = row(
            "m-cross-15",
            15,
            vec![attachment("a15", Some("image/gif"))],
            None,
        );
        cross.conversation_id = other.id.clone();
        insert(&cross);

        let older = store
            .list_adjacent_media(
                &account.id,
                &conversation.id,
                "m-anchor-50",
                AdjacentMediaDirection::Older,
                20,
            )
            .unwrap();
        assert_eq!(
            older.iter().map(|row| row.id.as_str()).collect::<Vec<_>>(),
            vec!["m-video-40", "m-image-10"],
            "adjacency-first, non-media rows and the cross-conversation row skipped"
        );
        let newer = store
            .list_adjacent_media(
                &account.id,
                &conversation.id,
                "m-anchor-50",
                AdjacentMediaDirection::Newer,
                20,
            )
            .unwrap();
        assert_eq!(
            newer.iter().map(|row| row.id.as_str()).collect::<Vec<_>>(),
            vec!["m-image-80"],
            "pdf, view-once, and unclassified attachments never join the strip"
        );
        // The anchor itself is never returned even when it carries media
        // (and the view-once row between is skipped, not matched).
        let anchored = store
            .list_adjacent_media(
                &account.id,
                &conversation.id,
                "m-image-80",
                AdjacentMediaDirection::Older,
                1,
            )
            .unwrap();
        assert_eq!(anchored.len(), 1);
        assert_eq!(anchored[0].id, "m-video-40");
        // limit truncates after full matches, not scanned rows.
        let limited = store
            .list_adjacent_media(
                &account.id,
                &conversation.id,
                "m-anchor-50",
                AdjacentMediaDirection::Older,
                1,
            )
            .unwrap();
        assert_eq!(limited.len(), 1);
        assert_eq!(limited[0].id, "m-video-40");
        // Ranges without media answer an empty vec, never an error.
        let empty = store
            .list_adjacent_media(
                &account.id,
                &conversation.id,
                "m-image-10",
                AdjacentMediaDirection::Older,
                20,
            )
            .unwrap();
        assert!(empty.is_empty());
        // A vanished anchor is a deterministic InvalidCursor, never a silent
        // re-anchor.
        let missing = store.list_adjacent_media(
            &account.id,
            &conversation.id,
            "m-gone",
            AdjacentMediaDirection::Older,
            20,
        );
        assert!(matches!(missing, Err(StoreError::InvalidCursor)));
    }

    /// Contract 1.93 (§4.76): rows sharing the anchor's sent_at order by id
    /// (the keyset tiebreak), and the scan crosses chunk boundaries — a
    /// media-bearing row further than one bounded chunk of non-media rows is
    /// still found without loading the whole range at once.
    #[test]
    fn list_adjacent_media_tiebreaks_by_id_and_crosses_scan_chunks() {
        use crate::engine::NormalizedAttachment;
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let attachment = |id: &str| NormalizedAttachment {
            id: id.into(),
            content_type: Some("image/jpeg".to_string()),
            filename: None,
            size: Some(1024),
            width: None,
            height: None,
            is_voice_note: false,
            caption: None,
            blur_hash: None,
            incremental_mac: None,
            chunk_size: None,
            is_borderless: false,
            is_gif: false,
            locator: None,
            waveform: None,
            duration: None,
        };
        let row = |id: &str, sent_at: u64, media: bool| MessageRecord {
            author_aci: None,
            id: id.into(),
            account_id: account.id.clone(),
            conversation_id: conversation.id.clone(),
            direction: "incoming",
            sender_id: "peer".into(),
            sender_name: None,
            mentions_self: false,
            sent_at,
            received_at: None,
            text: None,
            text_bytes: None,
            text_truncated: false,
            text_retrievable: false,
            status: "delivered",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: if media {
                vec![attachment(id)]
            } else {
                Vec::new()
            },
            rich: None,
            edited_at: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            admin_deleted: false,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        // Same sent_at as the anchor: id below the anchor is older, id above
        // is newer — the tiebreak matches list_messages' keyset order.
        store
            .insert_message(&row("m-tie-a", 50, true), None, None, false)
            .unwrap();
        store
            .insert_message(&row("m-tie-z", 50, true), None, None, false)
            .unwrap();
        store
            .insert_message(&row("m-tie-m", 50, false), None, None, false)
            .unwrap();
        let older = store
            .list_adjacent_media(
                &account.id,
                &conversation.id,
                "m-tie-m",
                AdjacentMediaDirection::Older,
                20,
            )
            .unwrap();
        assert_eq!(
            older.iter().map(|row| row.id.as_str()).collect::<Vec<_>>(),
            vec!["m-tie-a"]
        );
        let newer = store
            .list_adjacent_media(
                &account.id,
                &conversation.id,
                "m-tie-m",
                AdjacentMediaDirection::Newer,
                20,
            )
            .unwrap();
        assert_eq!(
            newer.iter().map(|row| row.id.as_str()).collect::<Vec<_>>(),
            vec!["m-tie-z"]
        );

        // More than one bounded scan chunk (128) of non-media rows between
        // the anchor and the next media row: the scan crosses chunks.
        for index in 0..(ADJACENT_MEDIA_SCAN_CHUNK as u64 + 10) {
            let id = format!("m-fill-{index:04}");
            store
                .insert_message(&row(&id, 100 + index, false), None, None, false)
                .unwrap();
        }
        store
            .insert_message(&row("m-far-media", 1_000, true), None, None, false)
            .unwrap();
        let found = store
            .list_adjacent_media(
                &account.id,
                &conversation.id,
                "m-tie-z",
                AdjacentMediaDirection::Newer,
                20,
            )
            .unwrap();
        assert_eq!(
            found.iter().map(|row| row.id.as_str()).collect::<Vec<_>>(),
            vec!["m-far-media"]
        );
    }

    /// Contract 1.34: the receipt selection queries — absent-`messageIds`
    /// mode orders incoming rows by `sent_at ASC, id ASC` under the caller's
    /// limit and skips outgoing rows; explicit-`messageIds` mode additionally
    /// drops unknown ids and collapses duplicates; `contact_peer_keys` only
    /// surfaces kind='contact' rows for mention-number resolution.
    #[test]
    fn receipt_selection_queries_order_filter_and_bound() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let base = |id: &str, sent_at: u64, direction: &'static str| MessageRecord {
            author_aci: None,
            id: id.into(),
            account_id: account.id.clone(),
            conversation_id: conversation.id.clone(),
            direction,
            sender_id: if direction == "incoming" {
                "peer".into()
            } else {
                "self".into()
            },
            sender_name: None,
            mentions_self: false,
            sent_at,
            received_at: None,
            text: Some("body".into()),
            text_bytes: Some(4),
            text_truncated: false,
            text_retrievable: true,
            status: if direction == "incoming" {
                "delivered"
            } else {
                "sent"
            },
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            edited_at: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        let now = now_ms();
        for (id, sent_at, direction) in [
            ("m3", now + 2, "incoming"),
            ("out-1", now + 3, "outgoing"),
            ("m1", now, "incoming"),
            ("m2", now + 1, "incoming"),
        ] {
            assert!(
                store
                    .insert_message(&base(id, sent_at, direction), None, Some("body"), true)
                    .unwrap()
            );
        }

        let bounded = store
            .incoming_rows_for_receipts(
                &account.id,
                &conversation.id,
                2,
                ReceiptResupply::UnissuedRead,
            )
            .unwrap();
        assert_eq!(
            bounded
                .iter()
                .map(|row| row.id.as_str())
                .collect::<Vec<_>>(),
            ["m1", "m2"]
        );

        let picked = store
            .incoming_rows_by_ids(
                &account.id,
                &conversation.id,
                &[
                    "m3".into(),
                    "m1".into(),
                    "out-1".into(),
                    "m3".into(),
                    "missing".into(),
                ],
            )
            .unwrap();
        assert_eq!(
            picked.iter().map(|row| row.id.as_str()).collect::<Vec<_>>(),
            ["m1", "m3"]
        );
        assert_eq!(picked[0].sent_at, now);
        assert_eq!(picked[1].sent_at, now + 2);

        store
            .upsert_synced_contacts(
                &account.id,
                &[
                    SyncedContact {
                        kind: "contact",
                        peer_key: "+15555550101",
                        title: "Peer",
                        extra: None,
                    },
                    SyncedContact {
                        kind: "group",
                        peer_key: "ZmFrZS1ncm91cC0x",
                        title: "Group",
                        extra: None,
                    },
                ],
                1,
            )
            .unwrap();
        assert_eq!(
            store.contact_peer_keys(&account.id).unwrap(),
            ["+15555550101"]
        );
    }

    /// §4.119 stopgap: the absent receipt selection only reaches inside the
    /// seven-day recency window, the viewed face skips already-stamped rows
    /// while the read face still selects them, a row exactly at the cutoff is
    /// excluded (strictly older-than semantics), and neither filter touches
    /// the explicit-`messageIds` mode.
    #[test]
    fn receipt_absent_selection_stays_inside_the_recency_window_and_viewed_boundary() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let now = now_ms();
        let seed = |store: &Store, id: &str, sent_at: u64| {
            let record = MessageRecord {
                author_aci: None,
                id: id.into(),
                account_id: account.id.clone(),
                conversation_id: conversation.id.clone(),
                direction: "incoming",
                sender_id: "peer".into(),
                sender_name: None,
                mentions_self: false,
                sent_at,
                received_at: None,
                text: Some("body".into()),
                text_bytes: Some(4),
                text_truncated: false,
                text_retrievable: true,
                status: "delivered",
                client_request_id: None,
                quote_message_id: None,
                quote_snapshot: None,
                quote: None,
                attachments: Vec::new(),
                rich: None,
                edited_at: None,
                reactions: Vec::new(),
                edits: Vec::new(),
                delivered_at: None,
                read_at: None,
                viewed_at: None,
                send_outcomes: None,
                sticker: None,
                expire_seconds: None,
                expire_start_at: None,
                admin_deleted: false,
                server_guid: None,
                server_timestamp: None,
                is_story: false,
                story_message: None,
            };
            assert!(
                store
                    .insert_message(&record, None, Some("body"), true)
                    .unwrap()
            );
        };
        let day: u64 = 24 * 60 * 60 * 1_000;
        seed(&store, "overage", now - 8 * day);
        seed(&store, "at-cutoff", now - 7 * day);
        seed(&store, "in-window-old", now - 6 * day);
        seed(&store, "in-window-fresh", now - 3_600_000);

        // Both faces agree inside the window: the overage rows (eight days
        // old, and exactly at the cutoff — strictly older-than) never select.
        let viewed = store
            .incoming_rows_for_receipts(
                &account.id,
                &conversation.id,
                512,
                ReceiptResupply::UnplayedViewed,
            )
            .unwrap();
        assert_eq!(
            viewed.iter().map(|row| row.id.as_str()).collect::<Vec<_>>(),
            ["in-window-old", "in-window-fresh"]
        );
        let read = store
            .incoming_rows_for_receipts(
                &account.id,
                &conversation.id,
                512,
                ReceiptResupply::UnissuedRead,
            )
            .unwrap();
        assert_eq!(
            read.iter().map(|row| row.id.as_str()).collect::<Vec<_>>(),
            ["in-window-old", "in-window-fresh"]
        );

        // The first viewed stamp (§4.77) becomes the resupply boundary: the
        // stamped row drops out of the viewed face. The read face carries its
        // own ledger (§4.163 `read_receipt_sent_at`) — nothing has stamped
        // read issuance here, so the stamped-for-viewed row still selects.
        assert_eq!(
            store
                .stamp_incoming_viewed(
                    &account.id,
                    &conversation.id,
                    &["in-window-old".into()],
                    now,
                )
                .unwrap(),
            1
        );
        let viewed_after = store
            .incoming_rows_for_receipts(
                &account.id,
                &conversation.id,
                512,
                ReceiptResupply::UnplayedViewed,
            )
            .unwrap();
        assert_eq!(
            viewed_after
                .iter()
                .map(|row| row.id.as_str())
                .collect::<Vec<_>>(),
            ["in-window-fresh"]
        );
        let read_after = store
            .incoming_rows_for_receipts(
                &account.id,
                &conversation.id,
                512,
                ReceiptResupply::UnissuedRead,
            )
            .unwrap();
        assert_eq!(
            read_after
                .iter()
                .map(|row| row.id.as_str())
                .collect::<Vec<_>>(),
            ["in-window-old", "in-window-fresh"]
        );

        // The explicit-`messageIds` mode applies neither filter: the stamped
        // row still resolves, and even an overage row stays addressable.
        let explicit = store
            .incoming_rows_by_ids(
                &account.id,
                &conversation.id,
                &["in-window-old".into(), "overage".into()],
            )
            .unwrap();
        assert_eq!(
            explicit
                .iter()
                .map(|row| row.id.as_str())
                .collect::<Vec<_>>(),
            ["overage", "in-window-old"]
        );
    }

