    /// A contacts sync batch is one transaction: when an entry in the middle
    /// fails, none of the rows and not even the sync marker become visible.
    /// Fault injection uses a trigger on a second connection, the same pattern
    /// as the receive-persistence failure test in supervisor.rs.
    #[test]
    fn synced_contacts_batch_rolls_back_atomically_on_failure() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let observer = keyed_observer(&store);
        observer
            .execute_batch(
                "CREATE TRIGGER fail_contact_insert
                 BEFORE INSERT ON contacts
                 WHEN NEW.peer_key='+15555550102'
                 BEGIN SELECT RAISE(FAIL, 'controlled test failure'); END;",
            )
            .unwrap();

        let entries = [
            SyncedContact {
                kind: "contact",
                peer_key: "+15555550101",
                title: "Alice",
                extra: None,
            },
            SyncedContact {
                kind: "contact",
                peer_key: "+15555550102",
                title: "Bob",
                extra: None,
            },
            SyncedContact {
                kind: "group",
                peer_key: "Z3JvdXAtMQ==",
                title: "Group",
                extra: Some("{\"memberCount\":2}"),
            },
        ];
        assert!(matches!(
            store.upsert_synced_contacts(&account.id, &entries, 42),
            Err(StoreError::Unavailable(_))
        ));
        // Nothing from the failed batch is visible, and the sync marker did
        // not advance, so the next sync is not short-circuited.
        assert_eq!(store.count_contacts(&account.id).unwrap(), (0, 0));
        assert_eq!(store.contacts_synced_at(&account.id).unwrap(), None);

        observer
            .execute_batch("DROP TRIGGER fail_contact_insert;")
            .unwrap();
        store
            .upsert_synced_contacts(&account.id, &entries, 43)
            .unwrap();
        assert_eq!(store.count_contacts(&account.id).unwrap(), (2, 1));
        assert_eq!(store.contacts_synced_at(&account.id).unwrap(), Some(43));

        // Same upsert semantics as the single-row path: a re-sync updates the
        // stored title and extra in place.
        let renamed = [SyncedContact {
            kind: "contact",
            peer_key: "+15555550101",
            title: "Alice A.",
            extra: None,
        }];
        store
            .upsert_synced_contacts(&account.id, &renamed, 44)
            .unwrap();
        let page = store
            .list_contacts(&account.id, Some("alice"), 10, None)
            .unwrap();
        assert_eq!(page.items.len(), 1);
        assert_eq!(page.items[0].title, "Alice A.");
        assert_eq!(store.count_contacts(&account.id).unwrap(), (2, 1));
    }

    /// Contract 1.136 (§4.122) as amended by 1.14b (§6.5): the passive contacts
    /// batch shares the pull batch's upsert columns but **never materializes a
    /// conversation** — a contact is not a chat — and never moves the pull
    /// marker (`contacts_synced_at` means "a full `listContacts` pull
    /// completed"). The change set therefore only ever names a placeholder
    /// title upgrade on a conversation that already exists.
    #[test]
    fn passive_contacts_batch_keeps_the_pull_marker_and_never_creates_conversations() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();

        let entries = [
            SyncedContact {
                kind: "contact",
                peer_key: "+15555550101",
                title: "Alice",
                extra: None,
            },
            SyncedContact {
                kind: "contact",
                peer_key: "+15555550102",
                title: "Bob",
                extra: None,
            },
        ];
        let changed = store
            .upsert_passive_contacts(&account.id, &entries, 42)
            .unwrap();
        // P0 regression: neither direct contact produces a conversation.
        assert!(changed.is_empty(), "{changed:?}");
        assert_eq!(store.contacts_synced_at(&account.id).unwrap(), None);
        assert_eq!(store.count_contacts(&account.id).unwrap(), (2, 0));
        for peer_key in ["+15555550101", "+15555550102"] {
            assert!(
                store
                    .conversation_by_peer(&account.id, "direct", peer_key)
                    .unwrap()
                    .is_none(),
                "a direct contact alone must not become a chat"
            );
        }

        // A replay of the same batch is a no-op change set.
        let changed = store
            .upsert_passive_contacts(&account.id, &entries, 43)
            .unwrap();
        assert!(changed.is_empty(), "{changed:?}");

        // A real name upgrades a masked conversation title and reports it;
        // the marker still belongs to the pull path alone.
        store
            .ensure_conversation(&account.id, "direct", "+15555550103", "8fc***e2")
            .unwrap();
        let upgrade = [SyncedContact {
            kind: "contact",
            peer_key: "+15555550103",
            title: "Carol",
            extra: None,
        }];
        let changed = store
            .upsert_passive_contacts(&account.id, &upgrade, 44)
            .unwrap();
        assert_eq!(changed.len(), 1, "{changed:?}");
        let conversation = store
            .conversation_by_peer(&account.id, "direct", "+15555550103")
            .unwrap()
            .expect("the conversation stays");
        let summary = store
            .conversation_summary(&account.id, &conversation.id)
            .unwrap()
            .expect("the upgraded conversation summarizes");
        assert_eq!(summary.title, "Carol");
        assert_eq!(store.contacts_synced_at(&account.id).unwrap(), None);

        // The pull path's marker write is untouched by all of the above.
        store
            .upsert_synced_contacts(&account.id, &entries, 45)
            .unwrap();
        assert_eq!(store.contacts_synced_at(&account.id).unwrap(), Some(45));
    }

    /// Contract 1.140 (§4.135) as amended by 1.14b (§6.5): the pull batch and
    /// the §4.122 passive batch report the same change set — a placeholder
    /// title upgrade on an **already existing** conversation. Neither creates a
    /// conversation: a contact is not a chat (P0 crosstalk fix). A replay
    /// changes nothing, and the sync marker still belongs to the pull.
    #[test]
    fn synced_contacts_pull_only_upgrades_existing_conversations() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();

        let entries = [
            SyncedContact {
                kind: "contact",
                peer_key: "+15555550101",
                title: "Alice",
                extra: None,
            },
            SyncedContact {
                kind: "group",
                peer_key: "Z3JvdXAtMQ==",
                title: "Group",
                extra: None,
            },
        ];
        let changed = store
            .upsert_synced_contacts(&account.id, &entries, 42)
            .unwrap();
        // P0 regression: the direct contact creates no conversation. The synced
        // **group** still materializes (structural membership — you are in it),
        // and it is the only conversation the change set names.
        assert_eq!(changed.len(), 1, "{changed:?}");
        assert!(
            store
                .conversation_by_peer(&account.id, "direct", "+15555550101")
                .unwrap()
                .is_none(),
            "a contact alone must not become a chat"
        );
        let group_row = store
            .conversation_by_peer(&account.id, "group", "Z3JvdXAtMQ==")
            .unwrap()
            .expect("a synced group is structurally a chat");
        assert_eq!(changed, vec![group_row.id.clone()]);

        // A replay of the same batch is a no-op change set; the marker still
        // advances (the pull owns it, the §4.122 passive face never does).
        let changed = store
            .upsert_synced_contacts(&account.id, &entries, 43)
            .unwrap();
        assert!(changed.is_empty(), "{changed:?}");
        assert_eq!(store.contacts_synced_at(&account.id).unwrap(), Some(43));

        // A real name upgrades a masked conversation title and reports it.
        store
            .ensure_conversation(&account.id, "direct", "+15555550103", "8fc***e2")
            .unwrap();
        let upgrade = [SyncedContact {
            kind: "contact",
            peer_key: "+15555550103",
            title: "Carol",
            extra: None,
        }];
        let changed = store
            .upsert_synced_contacts(&account.id, &upgrade, 44)
            .unwrap();
        assert_eq!(changed.len(), 1, "{changed:?}");
        let conversation = store
            .conversation_by_peer(&account.id, "direct", "+15555550103")
            .unwrap()
            .expect("the conversation stays");
        let summary = store
            .conversation_summary(&account.id, &conversation.id)
            .unwrap()
            .expect("the upgraded conversation summarizes");
        assert_eq!(summary.title, "Carol");
    }

    /// Schema 33 (contract 1.201, §6.5 amendment): a store written by an older
    /// binary still carries phantom direct conversations — rows a contacts sync
    /// materialized for people the account never messaged. The migration deletes
    /// exactly those, keeping every row that has a message, every group row and
    /// the Note-to-Self skeleton.
    #[test]
    fn schema_33_and_34_delete_empty_direct_conversations_only() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+447434026244", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        // The other account whose identities leaked in — the migration keys on
        // "this peer belongs to a *different* account".
        let other = store
            .upsert_account_from_signal("+8618827970450", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        store
            .set_account_aci(&other.id, Some("b1d73c45-8225-4421-bcf8-7b2f57442865"))
            .unwrap();
        // A real conversation (has a message) and a group (structural) survive.
        let real = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Real peer")
            .unwrap();
        store
            .seed_message_row_for_test(&account.id, &real.id)
            .unwrap();
        let group = store
            .ensure_conversation(&account.id, "group", "Z3JvdXA=", "Group")
            .unwrap();
        // A Note-to-Self skeleton (peer == own number) also survives.
        let memo = store
            .ensure_conversation(&account.id, "direct", "+447434026244", "Note to Self")
            .unwrap();
        // Phantom rows: direct conversations nobody ever messaged.
        let phantom_a = store
            .ensure_conversation(&account.id, "direct", "+8618827970450", "+86***50")
            .unwrap();
        let phantom_b = store
            .ensure_conversation(
                &account.id,
                "direct",
                "b1d73c45-8225-4421-bcf8-7b2f57442865",
                "bx y",
            )
            .unwrap();
        // The kind the 33 pass missed: an empty direct row keyed by the other
        // account contact ACI - never present in `accounts`, so only the
        // protocol rule ("no message, no thread") can recognize it.
        let phantom_c = store
            .ensure_conversation(
                &account.id,
                "direct",
                "8fc7f3b1-c017-4c89-b55c-d106dfaa2fe2",
                "菲菲 林",
            )
            .unwrap();
        // Rewind the schema marker so the migration runs on reopen.
        store.force_schema_version_for_test(32).unwrap();
        drop(store);

        let reopened = Store::open(temp.path(), Some(test_store_key())).unwrap();
        assert!(
            reopened
                .conversation_by_peer(&account.id, "direct", "+15555550101")
                .unwrap()
                .is_some(),
            "a messaged conversation must survive"
        );
        assert!(
            reopened
                .conversation_by_peer(&account.id, "group", "Z3JvdXA=")
                .unwrap()
                .is_some(),
            "a group row must survive"
        );
        assert!(
            reopened
                .conversation_by_peer(&account.id, "direct", "+447434026244")
                .unwrap()
                .is_some(),
            "the Note-to-Self skeleton must survive"
        );
        assert!(
            reopened
                .conversation_by_peer(&account.id, "direct", "+8618827970450")
                .unwrap()
                .is_none(),
            "the other account's number-keyed phantom row must be gone"
        );
        assert!(
            reopened
                .conversation_by_peer(
                    &account.id,
                    "direct",
                    "b1d73c45-8225-4421-bcf8-7b2f57442865"
                )
                .unwrap()
                .is_none(),
            "the phantom row must be gone"
        );
        assert!(
            reopened
                .conversation_by_peer(
                    &account.id,
                    "direct",
                    "8fc7f3b1-c017-4c89-b55c-d106dfaa2fe2"
                )
                .unwrap()
                .is_none(),
            "an empty direct row keyed by a foreign contact ACI must be gone too"
        );
        let _ = (group, memo, phantom_a, phantom_b, phantom_c);
    }

    /// **P0 regression (cross-account crosstalk, 2026-10-20).** Two accounts on
    /// one connector. Account B stores account A's number, so A's profile sync
    /// delivers A's identities into B's contacts cache. Before the §6.5
    /// amendment that contact sync materialized conversations, and B's chat
    /// list grew rows for people B had never messaged — rows whose peer keys
    /// were A's own identities (bx y / 菲菲 林 / y y on the real device).
    ///
    /// The invariant: a contacts sync never creates a conversation, on either
    /// the pull face or the passive face, for either account — and each
    /// account's cache stays in its own domain.
    #[test]
    fn contacts_sync_never_crosses_the_account_boundary_into_chat_lists() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let a = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let b = store
            .upsert_account_from_signal("+447434026244", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();

        // A's own ACI plus two of A's contacts: exactly the identities that
        // leaked into B's chat list on the real device.
        let a_aci = "b1d73c45-8225-4421-bcf8-7b2f57442865";
        let a_contact_1 = "8fc7f3b1-c017-4c89-b55c-d106dfaa2fe2";
        let a_contact_2 = "c9bf3cad-0efd-447e-963f-3f5e40d4324b";

        // B stores A's number as a contact, so A's profile sync lands every one
        // of A's identities in B's cache.
        let b_entries = [
            SyncedContact {
                kind: "contact",
                peer_key: a_aci,
                title: "bx y",
                extra: None,
            },
            SyncedContact {
                kind: "contact",
                peer_key: a_contact_1,
                title: "菲菲 林",
                extra: None,
            },
            SyncedContact {
                kind: "contact",
                peer_key: a_contact_2,
                title: "y y",
                extra: None,
            },
            SyncedContact {
                kind: "contact",
                peer_key: "+8618827970450",
                title: "",
                extra: None,
            },
        ];
        let changed = store.upsert_synced_contacts(&b.id, &b_entries, 10).unwrap();
        assert!(
            changed.is_empty(),
            "pull face created conversations: {changed:?}"
        );
        let changed = store
            .upsert_passive_contacts(&b.id, &b_entries, 11)
            .unwrap();
        assert!(
            changed.is_empty(),
            "passive face created conversations: {changed:?}"
        );

        // B's chat list is still empty — the whole point of the fix.
        let page = store.list_conversations(&b.id, 50, None).unwrap();
        assert!(page.items.is_empty(), "B has phantom chats: {page:?}");

        // A's domain is untouched and independent: A sending to a real peer
        // still creates A's own conversation, never B's.
        let a_conversation = store
            .ensure_conversation(&a.id, "direct", a_contact_1, "菲菲 林")
            .unwrap();
        let b_page = store.list_conversations(&b.id, 50, None).unwrap();
        assert!(b_page.items.is_empty(), "A's conversation leaked into B");
        let a_page = store.list_conversations(&a.id, 50, None).unwrap();
        assert_eq!(a_page.items.len(), 1);
        assert_eq!(a_page.items[0].id, a_conversation.id);
        assert_eq!(a_page.items[0].account_id, a.id);

        // Both accounts know the same peer key, yet each conversation id is
        // account-scoped: the fixed hash inputs keep the domains disjoint.
        let b_conversation = store
            .ensure_conversation(&b.id, "direct", a_contact_1, "菲菲 林")
            .unwrap();
        assert_ne!(b_conversation.id, a_conversation.id);
        assert_eq!(b_conversation.account_id, b.id);
        let b_page = store.list_conversations(&b.id, 50, None).unwrap();
        assert_eq!(b_page.items.len(), 1, "exactly the one B actually created");
        assert_eq!(b_page.items[0].account_id, b.id);

        // Counter-proof that the fix is not over-broad: a group B was synced
        // into still materializes its skeleton (structural membership).
        let group_entries = [SyncedContact {
            kind: "group",
            peer_key: "Z3JvdXAtYnktc3luYw==",
            title: "B's group",
            extra: None,
        }];
        let changed = store
            .upsert_synced_contacts(&b.id, &group_entries, 12)
            .unwrap();
        assert_eq!(changed.len(), 1, "the group skeleton must materialize");
        let group_row = store
            .conversation_by_peer(&b.id, "group", "Z3JvdXAtYnktc3luYw==")
            .unwrap()
            .expect("a synced group is structurally a chat");
        assert_eq!(group_row.account_id, b.id);
        // A's chat list is unaffected by B's group.
        assert_eq!(
            store
                .list_conversations(&a.id, 50, None)
                .unwrap()
                .items
                .len(),
            1
        );
    }

    /// Performance sanity, not a benchmark: a phone-scale contacts sync (a few
    /// thousand entries) must commit as one quick batch, not one transaction
    /// per row. Generous bound so slow CI machines still pass.
    #[test]
    fn synced_contacts_batch_handles_a_phone_scale_sync_quickly() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let keys: Vec<String> = (0..5_000)
            .map(|index| format!("+1555556{index:04}"))
            .collect();
        let entries: Vec<SyncedContact<'_>> = keys
            .iter()
            .map(|key| SyncedContact {
                kind: "contact",
                peer_key: key.as_str(),
                title: "Batch Contact",
                extra: None,
            })
            .collect();

        let started = std::time::Instant::now();
        store
            .upsert_synced_contacts(&account.id, &entries, 100)
            .unwrap();
        let elapsed = started.elapsed();

        assert_eq!(store.count_contacts(&account.id).unwrap(), (5_000, 0));
        assert_eq!(store.contacts_synced_at(&account.id).unwrap(), Some(100));
        assert!(
            elapsed < Duration::from_secs(5),
            "one 5000-row sync batch took {elapsed:?}, far above a single-transaction budget"
        );
    }

    #[test]
    fn schema_v4_upgrade_creates_contacts_table_before_advancing_version() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        store
            .conn()
            .execute_batch(
                "DROP TABLE contacts;
                 UPDATE meta SET value='4' WHERE key='schema_version';",
            )
            .unwrap();
        drop(store);

        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let count: i64 = store
            .conn()
            .query_row(
                "SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name='contacts'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(count, 1);
        let version: i64 = store
            .conn()
            .query_row(
                "SELECT CAST(value AS INTEGER) FROM meta WHERE key='schema_version'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(version, SCHEMA_VERSION);
    }

    #[test]
    fn message_pages_resume_after_retention_removed_the_anchor() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let now = 40 * 365 * 24 * 60 * 60 * 1_000;
        let day = 24 * 60 * 60 * 1_000;
        let (account, conversation, ids) =
            seed_history(&store, now, &[100 * day, 200 * day, 300 * day]);

        let first = store
            .list_messages(&account.id, &conversation.id, 1, None)
            .unwrap();
        assert_eq!(first.items[0].id, ids[0]);
        let cursor = first.next_cursor.unwrap();
        // Everything the caller has seen and its anchor expire underneath it.
        assert_eq!(
            store.prune_history(now, u32::MAX).unwrap().messages_deleted,
            3
        );

        // The page still resolves; it is simply empty now that the tail is gone.
        let next = store
            .list_messages(&account.id, &conversation.id, 10, Some(&cursor))
            .unwrap();
        assert!(next.items.is_empty());
        assert!(next.next_cursor.is_none());
    }

    #[test]
    fn retention_repairs_a_preview_whose_anchor_shared_a_timestamp() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let now = 40 * 365 * 24 * 60 * 60 * 1_000;
        let day = 24 * 60 * 60 * 1_000;
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let mut message = MessageRecord {
            author_aci: None,
            id: "kept".into(),
            account_id: account.id.clone(),
            conversation_id: conversation.id.clone(),
            direction: "incoming",
            sender_id: "peer".into(),
            sender_name: None,
            mentions_self: false,
            sent_at: now - 10 * day,
            received_at: Some(now - 10 * day),
            text: Some("kept body".into()),
            text_bytes: Some(9),
            text_truncated: false,
            text_retrievable: true,

            status: "delivered",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            edited_at: None,
            rich: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        store
            .insert_message(&message, None, Some("kept body"), true)
            .unwrap();
        backdate(&store, "kept", now - 8 * day);
        // Same timestamp as the row that stays, so a timestamp-only check would
        // conclude the summary is still anchored and leave a deleted preview.
        message.id = "expired".into();
        message.text = Some("expired body".into());
        store
            .insert_message(&message, None, Some("expired body"), true)
            .unwrap();
        backdate(&store, "expired", now - 400 * day);

        assert_eq!(
            store
                .prune_history(now, u32::MAX)
                .unwrap()
                .conversations_repaired,
            1
        );

        let summary = store
            .list_conversations(&account.id, 10, None)
            .unwrap()
            .items
            .remove(0);
        assert_eq!(summary.last_message_at, Some(now - 10 * day));
        assert_eq!(summary.last_message_preview.as_deref(), Some("kept body"));
    }

    #[test]
    fn retention_dates_history_written_before_the_stored_at_column() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let now = 40 * 365 * 24 * 60 * 60 * 1_000;
        let day = 24 * 60 * 60 * 1_000;
        let message = MessageRecord {
            author_aci: None,
            id: "before-upgrade".into(),
            account_id: account.id.clone(),
            conversation_id: conversation.id.clone(),
            direction: "incoming",
            sender_id: "peer".into(),
            sender_name: None,
            mentions_self: false,
            // Sender clock claims the epoch; we received it yesterday.
            sent_at: 5_000,
            received_at: Some(now - day),
            text: Some("body".into()),
            text_bytes: Some(4),
            text_truncated: false,
            text_retrievable: true,

            status: "delivered",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            edited_at: None,
            rich: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        store
            .insert_message(&message, None, Some("body"), true)
            .unwrap();
        store
            .conn()
            .execute_batch(
                // The held-since index is younger than schema 6, so a store
                // being reverted to its schema-5 shape cannot carry it — and
                // SQLite refuses to drop an indexed column.
                "DROP INDEX IF EXISTS messages_held_since;
                 ALTER TABLE messages DROP COLUMN stored_at;
                 UPDATE meta SET value='5' WHERE key='schema_version';",
            )
            .unwrap();
        drop(store);

        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();

        // The upgrade only adds the column; rewriting the table would delay the
        // startup handshake. Retention instead dates such a row by the time we
        // received it, so pre-upgrade history is not read as instantly expired.
        let stored_at: Option<i64> = store
            .conn()
            .query_row(
                "SELECT stored_at FROM messages WHERE id='before-upgrade'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(stored_at, None);
        assert_eq!(
            store.prune_history(now, u32::MAX).unwrap().messages_deleted,
            0
        );
        assert_eq!(stored_message_ids(&store, &conversation.id).len(), 1);
        let version: i64 = store
            .conn()
            .query_row(
                "SELECT CAST(value AS INTEGER) FROM meta WHERE key='schema_version'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(version, SCHEMA_VERSION);
    }

    /// Seed one conversation with messages at the given ages, newest first in
    /// the returned ids. `now` is the wall clock the retention pass will see.
    fn seed_history(
        store: &Store,
        now: u64,
        ages_ms: &[u64],
    ) -> (AccountSummary, ConversationRow, Vec<String>) {
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let ids = ages_ms
            .iter()
            .enumerate()
            .map(|(index, age)| {
                let id = format!("message-{index}");
                let message = MessageRecord {
                    author_aci: None,
                    id: id.clone(),
                    account_id: account.id.clone(),
                    conversation_id: conversation.id.clone(),
                    direction: "incoming",
                    sender_id: "peer".into(),
                    sender_name: None,
                    mentions_self: false,
                    sent_at: now - age,
                    received_at: Some(now - age),
                    text: Some("body".into()),
                    text_bytes: Some(4),
                    text_truncated: false,
                    text_retrievable: true,
                    status: "delivered",
                    client_request_id: None,
                    quote_message_id: None,
                    quote_snapshot: None,
                    quote: None,
                    attachments: Vec::new(),
                    edited_at: None,
                    rich: None,
                    reactions: Vec::new(),
                    edits: Vec::new(),
                    delivered_at: None,
                    read_at: None,
                    viewed_at: None,
                    send_outcomes: None,
                    sticker: None,
                    expire_seconds: None,
                    expire_start_at: None,
                    admin_deleted: false,
                    server_guid: None,
                    server_timestamp: None,
                    is_story: false,
                    story_message: None,
                };
                store
                    .insert_message(&message, None, Some("body"), true)
                    .unwrap();
                backdate(store, &id, now - age);
                id
            })
            .collect();
        (account, conversation, ids)
    }

    /// Pretend the store has held a row since `stored_at`; inserts always stamp
    /// the real clock, which no test can wait out.
    fn backdate(store: &Store, message_id: &str, stored_at: u64) {
        let updated = store
            .conn()
            .execute(
                "UPDATE messages SET stored_at=?2 WHERE id=?1",
                params![message_id, stored_at as i64],
            )
            .unwrap();
        assert_eq!(updated, 1);
    }

    fn stored_message_ids(store: &Store, conversation_id: &str) -> Vec<String> {
        let conn = store.conn();
        let mut stmt = conn
            .prepare("SELECT id FROM messages WHERE conversation_id=?1 ORDER BY id")
            .unwrap();
        stmt.query_map(params![conversation_id], |row| row.get::<_, String>(0))
            .unwrap()
            .collect::<Result<Vec<_>, _>>()
            .unwrap()
    }

    #[test]
    fn retention_drops_expired_history_and_keeps_the_rest() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let now = 40 * 365 * 24 * 60 * 60 * 1_000;
        let day = 24 * 60 * 60 * 1_000;
        let (account, conversation, ids) =
            seed_history(&store, now, &[day, 89 * day, 91 * day, 400 * day]);

        let outcome = store.prune_history(now, u32::MAX).unwrap();

        assert_eq!(outcome.messages_deleted, 2);
        let remaining = stored_message_ids(&store, &conversation.id);
        assert_eq!(remaining, vec![ids[0].clone(), ids[1].clone()]);
        // The seed inserted the oldest row last, so it owned the summary; the
        // repair moves the summary to the newest row still stored.
        assert_eq!(outcome.conversations_repaired, 1);
        let summary = store
            .list_conversations(&account.id, 10, None)
            .unwrap()
            .items
            .remove(0);
        assert_eq!(summary.last_message_at, Some(now - day));
    }

    #[test]
    fn retention_keeps_recent_history_beyond_the_per_conversation_cap() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let now = 40 * 365 * 24 * 60 * 60 * 1_000;
        // More rows than the cap allows, all inside the safety window: replay
        // dedupe and send idempotency still need every one of them.
        let ages = (0..(MAX_MESSAGES_PER_CONVERSATION as u64 + 5))
            .map(|index| index + 1)
            .collect::<Vec<_>>();
        let (_account, conversation, _ids) = seed_history(&store, now, &ages);

        assert_eq!(
            store.prune_history(now, u32::MAX).unwrap().messages_deleted,
            0
        );
        assert_eq!(
            stored_message_ids(&store, &conversation.id).len(),
            ages.len()
        );
    }

    #[test]
    fn retention_enforces_the_per_conversation_cap_outside_the_safety_window() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let now = 40 * 365 * 24 * 60 * 60 * 1_000;
        let day = 24 * 60 * 60 * 1_000;
        let over_cap = 3;
        // Old enough to prune, young enough that only the cap can select them.
        let ages = (0..(MAX_MESSAGES_PER_CONVERSATION as u64 + over_cap))
            .map(|index| 8 * day + index)
            .collect::<Vec<_>>();
        let (_account, conversation, ids) = seed_history(&store, now, &ages);

        let outcome = store.prune_history(now, u32::MAX).unwrap();

        assert_eq!(outcome.messages_deleted, over_cap);
        let remaining = stored_message_ids(&store, &conversation.id);
        assert_eq!(remaining.len(), MAX_MESSAGES_PER_CONVERSATION as usize);
        // The oldest rows go; the newest are what the cap keeps.
        for id in ids.iter().take(MAX_MESSAGES_PER_CONVERSATION as usize) {
            assert!(remaining.contains(id));
        }
        for id in ids.iter().skip(MAX_MESSAGES_PER_CONVERSATION as usize) {
            assert!(!remaining.contains(id));
        }
    }

