    /// §4.179 unknown-outcome reconciliation: the backlog query answers
    /// exactly this proxy group's unsettled outgoing rows — status='unknown'
    /// AND direction='outgoing' — joined with the engine lookup's addressing
    /// (signal account, conversation kind + peer_key), oldest first, bounded
    /// by the batch cap. Other groups' rows, settled rows, and incoming rows
    /// never enter the batch.
    #[test]
    fn unsettled_unknown_query_scopes_group_direction_and_bounds_batch() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let other_group = store
            .upsert_account_from_signal("+15555550200", Some(1), "other-group")
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let group_conversation = store
            .ensure_conversation(&account.id, "group", "GROUPKEY==", "Group")
            .unwrap();
        let other_conversation = store
            .ensure_conversation(&other_group.id, "direct", "+15555550201", "Other")
            .unwrap();

        let base = now_ms() - 10_000;
        let seed = |id: &str,
                    account_id: &str,
                    conversation_id: &str,
                    status: &'static str,
                    direction: &'static str,
                    sent_at: u64| {
            let record = MessageRecord {
                author_aci: None,
                id: id.into(),
                account_id: account_id.to_string(),
                conversation_id: conversation_id.to_string(),
                direction,
                sender_id: account_id.to_string(),
                sender_name: None,
                mentions_self: false,
                sent_at,
                received_at: None,
                text: Some("body".into()),
                text_bytes: Some(4),
                text_truncated: false,
                text_retrievable: true,
                status,
                client_request_id: None,
                quote_message_id: None,
                quote_snapshot: None,
                quote: None,
                attachments: Vec::new(),
                edited_at: None,
                rich: None,
                reactions: Vec::new(),
                edits: Vec::new(),
                delivered_at: None,
                read_at: None,
                viewed_at: None,
                send_outcomes: None,
                sticker: None,
                expire_seconds: None,
                expire_start_at: None,
                admin_deleted: false,
                server_guid: None,
                server_timestamp: None,
                is_story: false,
                story_message: None,
            };
            store
                .insert_message(&record, None, Some("body"), false)
                .unwrap();
        };
        seed(
            "unknown-1",
            &account.id,
            &conversation.id,
            "unknown",
            "outgoing",
            base,
        );
        seed(
            "unknown-2",
            &account.id,
            &group_conversation.id,
            "unknown",
            "outgoing",
            base + 1,
        );
        seed(
            "unknown-3",
            &account.id,
            &conversation.id,
            "unknown",
            "outgoing",
            base + 2,
        );
        // Distractors: settled, in-flight, incoming, and another group's row.
        seed(
            "settled",
            &account.id,
            &conversation.id,
            "sent",
            "outgoing",
            base + 3,
        );
        seed(
            "pending",
            &account.id,
            &conversation.id,
            "pending",
            "outgoing",
            base + 4,
        );
        seed(
            "incoming-unknown",
            &account.id,
            &conversation.id,
            "unknown",
            "incoming",
            base + 5,
        );
        seed(
            "other-group-unknown",
            &other_group.id,
            &other_conversation.id,
            "unknown",
            "outgoing",
            base + 6,
        );

        // Full backlog: exactly this group's three unsettled outgoing rows,
        // oldest first, with the engine lookup's addressing joined in.
        let rows = store
            .unsettled_unknown_outgoing_sends(DEFAULT_PROXY_GROUP_ID, 16)
            .unwrap();
        let ids: Vec<&str> = rows.iter().map(|row| row.id.as_str()).collect();
        assert_eq!(ids, ["unknown-1", "unknown-2", "unknown-3"]);
        assert_eq!(rows[0].signal_account, "+15555550100");
        assert_eq!(rows[0].conversation_kind, "direct");
        assert_eq!(rows[0].peer_key, "+15555550101");
        assert_eq!(rows[0].sent_at, base);
        assert_eq!(rows[1].conversation_kind, "group");
        assert_eq!(rows[1].peer_key, "GROUPKEY==");

        // Batch cap bounds the round: a short batch is the drained signal,
        // a full batch means another round follows (the pass loops).
        let bounded = store
            .unsettled_unknown_outgoing_sends(DEFAULT_PROXY_GROUP_ID, 2)
            .unwrap();
        assert_eq!(bounded.len(), 2);
        assert_eq!(bounded[0].id, "unknown-1");

        // A different group's backlog answers its own rows — and only those.
        let other_rows = store
            .unsettled_unknown_outgoing_sends("other-group", 16)
            .unwrap();
        assert_eq!(other_rows.len(), 1);
        assert_eq!(other_rows[0].id, "other-group-unknown");
        assert_eq!(other_rows[0].signal_account, "+15555550200");
    }

    /// §4.179 unknown-outcome reconciliation: the guarded settle. The sent
    /// arm keeps the row's original sent_at (the engine's matched-row
    /// timestamp stays engine-side) and bumps the conversation summary
    /// monotonically; the failed arm settles plain. The `status='unknown'`
    /// guard is the idempotency face: a second settle, and a settle aimed at
    /// a row that moved on (pending/sent), report None and change nothing.
    #[test]
    fn settle_unknown_send_is_guarded_and_keeps_sent_at() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let sent_at = now_ms() - 60_000;
        let record = MessageRecord {
            author_aci: None,
            id: "reconcile-row".into(),
            account_id: account.id.clone(),
            conversation_id: conversation.id.clone(),
            direction: "outgoing",
            sender_id: account.id.clone(),
            sender_name: None,
            mentions_self: false,
            sent_at,
            received_at: None,
            text: Some("body".into()),
            text_bytes: Some(4),
            text_truncated: false,
            text_retrievable: true,
            status: "unknown",
            client_request_id: Some("request-unknown".into()),
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            edited_at: None,
            rich: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        store
            .insert_message(&record, Some("request-unknown"), Some("body"), false)
            .unwrap();

        // dispatched=true: settled sent, sent_at preserved verbatim, real
        // transition reported, schedule faces clear, summary bumped to the
        // kept stamp.
        let (settled, transitioned) = store
            .settle_unknown_send("reconcile-row", true)
            .unwrap()
            .expect("unknown row settles");
        assert!(transitioned);
        assert_eq!(settled.status, "sent");
        assert_eq!(settled.sent_at, sent_at);
        let summary = store
            .conversation_summary(&account.id, &conversation.id)
            .unwrap()
            .expect("summary");
        assert_eq!(summary.last_message_at, Some(sent_at));

        // Idempotency: the row left unknown — a re-run reports None.
        assert!(
            store
                .settle_unknown_send("reconcile-row", false)
                .unwrap()
                .is_none()
        );
        let after = store
            .message_by_client_request(&account.id, "request-unknown")
            .unwrap()
            .expect("row");
        assert_eq!(after.status, "sent");

        // Guard: a settle aimed at a row that moved on changes nothing.
        store
            .update_message_status("reconcile-row", "pending", None)
            .unwrap();
        assert!(
            store
                .settle_unknown_send("reconcile-row", true)
                .unwrap()
                .is_none()
        );
        let pending = store
            .message_by_client_request(&account.id, "request-unknown")
            .unwrap()
            .expect("row");
        assert_eq!(pending.status, "pending");

        // dispatched=false arm: unknown -> failed, plain settle.
        store
            .update_message_status("reconcile-row", "unknown", None)
            .unwrap();
        let (failed, transitioned) = store
            .settle_unknown_send("reconcile-row", false)
            .unwrap()
            .expect("unknown row settles");
        assert!(transitioned);
        assert_eq!(failed.status, "failed");
        assert_eq!(failed.sent_at, sent_at);
    }

    #[test]
    fn retention_repairs_the_summaries_of_a_conversation_it_emptied() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let now = 40 * 365 * 24 * 60 * 60 * 1_000;
        let day = 24 * 60 * 60 * 1_000;
        let (account, conversation, _ids) = seed_history(&store, now, &[300 * day, 400 * day]);
        // Second conversation stays inside retention so the account keeps a
        // last-message time and an unread badge of its own.
        let kept = store
            .ensure_conversation(&account.id, "direct", "+15555550102", "contact")
            .unwrap();
        let recent = MessageRecord {
            author_aci: None,
            id: "recent".into(),
            account_id: account.id.clone(),
            conversation_id: kept.id.clone(),
            direction: "incoming",
            sender_id: "peer".into(),
            sender_name: None,
            mentions_self: false,
            sent_at: now - day,
            received_at: Some(now - day),
            text: Some("body".into()),
            text_bytes: Some(4),
            text_truncated: false,
            text_retrievable: true,

            status: "delivered",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            edited_at: None,
            rich: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        store
            .insert_message(&recent, None, Some("body"), true)
            .unwrap();

        let outcome = store.prune_history(now, u32::MAX).unwrap();

        assert_eq!(outcome.messages_deleted, 2);
        assert_eq!(outcome.conversations_repaired, 1);
        let conversations = store
            .list_conversations(&account.id, 10, None)
            .unwrap()
            .items;
        let emptied = conversations
            .iter()
            .find(|item| item.id == conversation.id)
            .unwrap();
        // The conversation survives so its title and pins do, but it may not
        // advertise a preview, a time or unread mail that no longer exists.
        assert_eq!(emptied.last_message_at, None);
        assert_eq!(emptied.last_message_preview, None);
        assert_eq!(emptied.unread_count, 0);
        let accounts = store.list_accounts().unwrap();
        let summary = accounts.iter().find(|item| item.id == account.id).unwrap();
        assert_eq!(summary.last_message_at, Some(now - day));
        assert_eq!(summary.unread_count, 1);
    }

    #[test]
    fn retention_repoints_a_summary_whose_newest_row_expired() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let now = 40 * 365 * 24 * 60 * 60 * 1_000;
        let day = 24 * 60 * 60 * 1_000;
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let mut message = MessageRecord {
            author_aci: None,
            id: "kept".into(),
            account_id: account.id.clone(),
            conversation_id: conversation.id.clone(),
            direction: "incoming",
            sender_id: "peer".into(),
            sender_name: None,
            mentions_self: false,
            sent_at: now - 20 * day,
            received_at: Some(now - 20 * day),
            text: Some("kept body".into()),
            text_bytes: Some(9),
            text_truncated: false,
            text_retrievable: true,

            status: "delivered",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            edited_at: None,
            rich: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        store
            .insert_message(&message, None, Some("kept body"), true)
            .unwrap();
        backdate(&store, "kept", now - 8 * day);
        // A peer clock running ahead makes this the newest row by sent_at, so the
        // conversation summary points at it, yet we have held it long enough to
        // expire. Pruning it must not leave the summary on a deleted row.
        message.id = "skewed".into();
        message.sent_at = now - 10 * day;
        message.text = Some("skewed body".into());
        store
            .insert_message(&message, None, Some("skewed body"), true)
            .unwrap();
        backdate(&store, "skewed", now - 400 * day);

        let outcome = store.prune_history(now, u32::MAX).unwrap();

        assert_eq!(outcome.messages_deleted, 1);
        assert_eq!(outcome.conversations_repaired, 1);
        let summary = store
            .list_conversations(&account.id, 10, None)
            .unwrap()
            .items
            .remove(0);
        assert_eq!(summary.last_message_at, Some(now - 20 * day));
        assert_eq!(summary.last_message_preview.as_deref(), Some("kept body"));
        let accounts = store.list_accounts().unwrap();
        assert_eq!(accounts[0].last_message_at, Some(now - 20 * day));
    }

