    /// The live locator column round-trips (contract revision 1.61, §4.54):
    /// a receive envelope's transit faces land index-aligned beside the
    /// descriptors, a metadata-only envelope lands the all-None faces, and
    /// both read back through `live_attachment_locators` — the wire
    /// descriptor stays byte-identical either way.
    #[test]
    fn live_locator_column_round_trips_index_aligned() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550105", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550106", "Peer")
            .unwrap();
        let descriptor = |id: &str, locator: Option<crate::store::HistoryAttachmentLocator>| {
            crate::engine::NormalizedAttachment {
                id: id.into(),
                content_type: Some("image/jpeg".into()),
                filename: None,
                size: Some(2048),
                width: None,
                height: None,
                is_voice_note: false,
                caption: None,
                blur_hash: None,
                incremental_mac: None,
                chunk_size: None,
                is_borderless: false,
                is_gif: false,
                locator,
                waveform: None,
                duration: None,
            }
        };
        let full_face = crate::store::HistoryAttachmentLocator {
            key: Some("a2F0LWtleQ==".into()),
            cdn_key: Some("live-key".into()),
            cdn_number: Some(3),
            upload_timestamp: Some(1700000000000),
            digest: Some("ZGl-nonsense".into()),
            plaintext_hash: Some("aabb".into()),
        };
        let mut with_face = expire_record("m-loc", &account.id, &conversation.id);
        with_face.attachments = vec![
            descriptor("att-a", Some(full_face.clone())),
            // The hole stays index-aligned: a metadata-only sibling keeps its
            // own all-None face instead of shifting the row.
            descriptor("att-b", None),
        ];
        store
            .insert_message(&with_face, None, Some("face"), true)
            .unwrap();
        let faces = store
            .live_attachment_locators(&account.id, "m-loc")
            .unwrap();
        assert_eq!(faces.len(), 2);
        assert_eq!(faces[0], full_face);
        assert_eq!(faces[1], crate::store::HistoryAttachmentLocator::default());

        let plain = expire_record("m-plain", &account.id, &conversation.id);
        store
            .insert_message(&plain, None, Some("plain"), true)
            .unwrap();
        assert!(
            store
                .live_attachment_locators(&account.id, "m-plain")
                .unwrap()
                .is_empty()
        );
    }

    /// merge_live_attachment_locators (contract revision 1.175, §4.175): the
    /// merge fills only empty slots — the optimistic outgoing row / the
    /// backfill response both land their pointer faces through this
    /// primitive. First face wins (an existing non-default slot is never
    /// overwritten); a longer new face extends the column index-aligned; an
    /// all-default new face and an absent row both answer `Ok(false)`.
    #[test]
    fn merge_live_attachment_locators_fills_only_empty_slots() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550105", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550106", "Peer")
            .unwrap();
        let descriptor = |id: &str, locator: Option<crate::store::HistoryAttachmentLocator>| {
            crate::engine::NormalizedAttachment {
                id: id.into(),
                content_type: Some("image/jpeg".into()),
                filename: None,
                size: Some(2048),
                width: None,
                height: None,
                is_voice_note: false,
                caption: None,
                blur_hash: None,
                incremental_mac: None,
                chunk_size: None,
                is_borderless: false,
                is_gif: false,
                locator,
                waveform: None,
                duration: None,
            }
        };
        let face = |cdn: &str| crate::store::HistoryAttachmentLocator {
            key: Some("a2F0LWtleQ==".into()),
            cdn_key: Some(cdn.into()),
            cdn_number: Some(3),
            upload_timestamp: Some(1700000000000),
            digest: Some("ZGl-nonsense".into()),
            plaintext_hash: None,
        };
        // The pre-echo outgoing row: descriptors without locators.
        let mut row = expire_record("m-merge", &account.id, &conversation.id);
        row.direction = "outgoing";
        row.attachments = vec![descriptor("att-a", None), descriptor("att-b", None)];
        store
            .insert_message(&row, None, Some("merge"), false)
            .unwrap();
        // The insert stored the all-default faces index-aligned (the 1.61
        // write discipline) — every slot is an empty hole waiting to fill.
        let initial = store
            .live_attachment_locators(&account.id, "m-merge")
            .unwrap();
        assert_eq!(initial.len(), 2);
        assert!(
            initial
                .iter()
                .all(|face| face == &crate::store::HistoryAttachmentLocator::default())
        );

        // The echo/backfill merge: index 0 lands, index 1 stays a hole for
        // now; a longer face extends the column.
        let changed = store
            .merge_live_attachment_locators(
                &account.id,
                "m-merge",
                &[Some(face("cdn-a")), None, Some(face("cdn-c"))],
            )
            .unwrap();
        assert!(changed);
        let faces = store
            .live_attachment_locators(&account.id, "m-merge")
            .unwrap();
        assert_eq!(faces.len(), 3);
        assert_eq!(faces[0], face("cdn-a"));
        assert_eq!(faces[1], crate::store::HistoryAttachmentLocator::default());
        assert_eq!(faces[2], face("cdn-c"));

        // First face wins: a second merge with a different face for index 0
        // changes nothing.
        let changed = store
            .merge_live_attachment_locators(
                &account.id,
                "m-merge",
                &[Some(face("cdn-OTHER")), Some(face("cdn-b"))],
            )
            .unwrap();
        assert!(changed, "index 1's empty slot still fills");
        let faces = store
            .live_attachment_locators(&account.id, "m-merge")
            .unwrap();
        assert_eq!(faces[0], face("cdn-a"), "existing slot never moves");
        assert_eq!(faces[1], face("cdn-b"));

        // All-default new face: quiet no-op.
        let changed = store
            .merge_live_attachment_locators(&account.id, "m-merge", &[None, None])
            .unwrap();
        assert!(!changed);

        // Absent row: quiet no-op.
        let changed = store
            .merge_live_attachment_locators(&account.id, "m-absent", &[Some(face("cdn-x"))])
            .unwrap();
        assert!(!changed);
    }

    /// `remove_message_attachment_at` (contract 1.196, §4.196): the
    /// official single-attachment delete mirror — the descriptor leaves and
    /// the same index leaves both locator columns, so surviving slots never
    /// shift onto a neighbour. An absent row, an index past the end, and a
    /// row with no descriptors answer `None` without writing.
    #[test]
    fn remove_message_attachment_at_strips_descriptor_and_aligned_locators() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550105", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550106", "Peer")
            .unwrap();
        let descriptor = |id: &str, locator: Option<HistoryAttachmentLocator>| {
            crate::engine::NormalizedAttachment {
                id: id.into(),
                content_type: Some("image/jpeg".into()),
                filename: None,
                size: Some(2048),
                width: None,
                height: None,
                is_voice_note: false,
                caption: None,
                blur_hash: None,
                incremental_mac: None,
                chunk_size: None,
                is_borderless: false,
                is_gif: false,
                locator,
                waveform: None,
                duration: None,
            }
        };
        let face = |digest: &str, hash: &str| HistoryAttachmentLocator {
            key: Some("a2F0LWtleQ==".into()),
            cdn_key: Some(format!("cdn-{digest}")),
            cdn_number: Some(3),
            upload_timestamp: Some(1700000000000),
            digest: Some(digest.into()),
            plaintext_hash: Some(hash.into()),
        };
        let mut row = expire_record("m-strip", &account.id, &conversation.id);
        row.attachments = vec![
            descriptor("att-a", Some(face("digest-a", "aa"))),
            descriptor("att-b", Some(face("digest-b", "bb"))),
            descriptor("att-c", Some(face("digest-c", "cc"))),
        ];
        store
            .insert_message(&row, None, Some("strip"), true)
            .unwrap();
        // Seed the history-import column too: the removal must keep both
        // index-aligned columns in step (they are separate columns because
        // the history import and the live receive write different faces).
        let history_faces = vec![
            face("digest-a", "aa"),
            face("digest-b", "bb"),
            face("digest-c", "cc"),
        ];
        store
            .conn()
            .execute(
                "UPDATE messages SET attachment_locators=?3 WHERE account_id=?1 AND id=?2",
                params![
                    account.id,
                    "m-strip",
                    serde_json::to_string(&history_faces).unwrap()
                ],
            )
            .unwrap();

        assert_eq!(
            store
                .remove_message_attachment_at(&account.id, "m-strip", 1)
                .unwrap()
                .as_deref(),
            Some("att-b")
        );
        let record = store
            .message_by_id(&account.id, &conversation.id, "m-strip")
            .unwrap()
            .expect("the message row survives an attachment delete");
        assert_eq!(
            record
                .attachments
                .iter()
                .map(|attachment| attachment.id.as_str())
                .collect::<Vec<_>>(),
            vec!["att-a", "att-c"]
        );
        let live = store
            .live_attachment_locators(&account.id, "m-strip")
            .unwrap();
        assert_eq!(live.len(), 2);
        assert_eq!(live[0].digest.as_deref(), Some("digest-a"));
        assert_eq!(live[1].digest.as_deref(), Some("digest-c"));
        let history = store
            .history_attachment_locators(&account.id, "m-strip")
            .unwrap();
        assert_eq!(history.len(), 2);
        assert_eq!(history[0].digest.as_deref(), Some("digest-a"));
        assert_eq!(history[1].digest.as_deref(), Some("digest-c"));

        // Out-of-range, absent row, and a descriptor-less row are quiet
        // misses: nothing is written.
        assert!(
            store
                .remove_message_attachment_at(&account.id, "m-strip", 9)
                .unwrap()
                .is_none()
        );
        assert!(
            store
                .remove_message_attachment_at(&account.id, "m-absent", 0)
                .unwrap()
                .is_none()
        );
        let mut plain = expire_record("m-plain-strip", &account.id, &conversation.id);
        plain.attachments = Vec::new();
        store
            .insert_message(&plain, None, Some("plain"), true)
            .unwrap();
        assert!(
            store
                .remove_message_attachment_at(&account.id, "m-plain-strip", 0)
                .unwrap()
                .is_none()
        );
    }

    /// serverGuid round-trip (contract revision 1.49, §4.48): a live receive
    /// row persists the envelope's serverGuid, and `server_guids_by_ids`
    /// answers a 1:1 list — the recorded guid for the row, None for missing
    /// rows and None for guid-less rows.
    #[test]
    fn server_guid_round_trip_and_lookup() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550101", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550102", "Peer")
            .unwrap();
        let mut with_guid = expire_record("m1", &account.id, &conversation.id);
        with_guid.server_guid = Some("guid-one".to_string());
        store.insert_message(&with_guid, None, None, true).unwrap();
        let without_guid = expire_record("m2", &account.id, &conversation.id);
        store
            .insert_message(&without_guid, None, None, true)
            .unwrap();

        let fetched = store
            .message_by_id(&account.id, &conversation.id, "m1")
            .unwrap()
            .unwrap();
        assert_eq!(fetched.server_guid.as_deref(), Some("guid-one"));
        let plain = store
            .message_by_id(&account.id, &conversation.id, "m2")
            .unwrap()
            .unwrap();
        assert_eq!(plain.server_guid, None);

        let guids = store
            .server_guids_by_ids(
                &account.id,
                &conversation.id,
                &["m1".into(), "missing".into(), "m2".into()],
            )
            .unwrap();
        assert_eq!(guids, vec![Some("guid-one".to_string()), None, None]);
    }

